/**
 * This is the comms subsystem of the runtime.
 * @mixin @node-red/runtime_comms
 */

/**
 * A WebSocket connection between the runtime and the editor.
 * @typedef CommsConnection
 * @type {object}
 * @property {string} session - a unique session identifier
 * @property {Object} user - the user associated with the connection
 * @property {Function} send - publish a message to the connection
 */


var runtime;
var retained = {};
var connections = [];
var inboundSubscriptions = {};

const events = require("@node-red/util").events;

function topicRegExp(topic) {
    return new RegExp("^"+topic.replace(/([\[\]\?\(\)\\\\$\^\*\.|])/g,"\\$1").replace(/\+/g,"[^/]+").replace(/\/#$/,"(\/.*)?")+"$");
}

function handleCommsEvent(event) {
    publish(event.topic,event.data,event.retain,event.session,event.excludeSession);
}
function handleStatusEvent(event) {
    if (!event.status) {
        delete retained["status/"+event.id]
    } else if (!event.status.text && !event.status.fill && !event.status.shape) {
        if (retained["status/"+event.id]) {
            publish("status/"+event.id,{},false);
        }
    } else {
        var status = {
            text: event.status.text,
            fill: event.status.fill,
            shape: event.status.shape
        };
        publish("status/"+event.id,status,true);
    }
}
function handleRuntimeEvent(event) {
    runtime.log.trace("runtime event: "+JSON.stringify(event));
    publish("notification/"+event.id,event.payload||{},event.retain);
}
function handleEventLog(event) {
    var type = event.payload.type;
    var id = event.id;
    if (event.payload.data) {
        var data = event.payload.data;
        if (data.endsWith('\n')) {
            data = data.substring(0,data.length-1);
        }
        var lines = data.split(/\n/);
        lines.forEach(line => {
            runtime.log.debug((type?("["+type+"] "):"")+line)
        })
    }
    publish("event-log/"+event.id,event.payload||{});
}

function publish(topic,data,retain,session,excludeSession) {
    if (session || excludeSession) {
        // Targeted messages are not retained. Otherwise a later reconnect or
        // subscription could deliver the message to a different session.
        retain = false;
    }
    if (retain) {
        retained[topic] = data;
    } else {
        delete retained[topic];
    }
    connections.forEach(connection => {
        if ((!session || connection.session === session) && (!excludeSession || connection.session !== excludeSession)) {
            connection.send(topic,data)
        }
    })
}

function receive(topic,data,connection,user) {
    events.emit("comms:message:"+topic,{
        topic: topic,
        session: connection.session,
        user: user,
        data: data
    });
    for (var subscriptionTopic in inboundSubscriptions) {
        if (inboundSubscriptions.hasOwnProperty(subscriptionTopic)) {
            var subscription = inboundSubscriptions[subscriptionTopic];
            if (subscription.re.test(topic)) {
                subscription.callbacks.forEach(callback => callback(topic,data,connection.session,user));
            }
        }
    }
}

function subscribeInbound(topic,callback) {
    if (!inboundSubscriptions[topic]) {
        inboundSubscriptions[topic] = {
            re: topicRegExp(topic),
            callbacks: []
        };
    }
    if (inboundSubscriptions[topic].callbacks.indexOf(callback) === -1) {
        inboundSubscriptions[topic].callbacks.push(callback);
    }
}

function unsubscribeInbound(topic,callback) {
    var subscription = inboundSubscriptions[topic];
    if (!subscription) {
        return;
    }
    if (callback) {
        var index = subscription.callbacks.indexOf(callback);
        if (index > -1) {
            subscription.callbacks.splice(index,1);
        }
    } else {
        subscription.callbacks = [];
    }
    if (subscription.callbacks.length === 0) {
        delete inboundSubscriptions[topic];
    }
}

var api = module.exports = {
    init: function(_runtime) {
        runtime = _runtime;
        connections = [];
        retained = {};
        inboundSubscriptions = {};
        events.removeListener("node-status",handleStatusEvent);
        events.on("node-status",handleStatusEvent);
        events.removeListener("runtime-event",handleRuntimeEvent);
        events.on("runtime-event",handleRuntimeEvent);
        events.removeListener("comms",handleCommsEvent);
        events.on("comms",handleCommsEvent);
        events.removeListener("event-log",handleEventLog);
        events.on("event-log",handleEventLog);
    },

    /**
    * Registers a new comms connection
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    addConnection: async function(opts) {
        connections.push(opts.client);
    },

    /**
    * Unregisters a comms connection
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    removeConnection: async function(opts) {
        for (var i=0;i<connections.length;i++) {
            if (connections[i] === opts.client) {
                connections.splice(i,1);
                break;
            }
        }
    },

    /**
    * Subscribes a comms connection to a given topic. Currently, all clients get
    * automatically subscribed to everything and cannot unsubscribe. Sending a subscribe
    * request will trigger retained messages to be sent.
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @param {String} opts.topic - the topic to subscribe to
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    subscribe: async function(opts) {
        var re = topicRegExp(opts.topic);
        for (var t in retained) {
            if (re.test(t)) {
                opts.client.send(t,retained[t]);
            }
        }
    },

    /**
    * TODO: Unsubscribes a comms connection from a given topic
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @param {String} opts.topic - the topic to unsubscribe from
    * @return {Promise<Object>} - resolves when complete
    * @memberof @node-red/runtime_comms
    */
    unsubscribe: async function(opts) {},

    /**
    * Subscribes runtime code to messages published by editor clients.
    * The callback receives: topic, data, session id and user object.
    * @param {Object} opts
    * @param {String} opts.topic - the topic to subscribe to; + and # wildcards are supported
    * @param {Function} opts.callback - the message handler
    * @return {Promise<void>} - resolves when registered
    * @memberof @node-red/runtime_comms
    */
    subscribeInbound: async function(opts) {
        subscribeInbound(opts.topic,opts.callback);
    },

    /**
    * Unsubscribes runtime code from messages published by editor clients.
    * @param {Object} opts
    * @param {String} opts.topic - the subscribed topic
    * @param {Function} [opts.callback] - the handler to remove; omit to remove all handlers
    * @return {Promise<void>} - resolves when unregistered
    * @memberof @node-red/runtime_comms
    */
    unsubscribeInbound: async function(opts) {
        unsubscribeInbound(opts.topic,opts.callback);
    },

    /**
    * Publishes a message to connected editor clients.
    * @param {String} topic - the topic to publish to
    * @param {*} data - the message payload
    * @param {Boolean} [retain] - whether to retain the message
    * @param {String} [session] - only send to this editor session
    * @param {String} [excludeSession] - send to every editor session except this one
    * @return {void}
    * @memberof @node-red/runtime_comms
    */
    publish: publish,

    /**
    * Delivers a message sent by an editor client.
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {CommsConnection} opts.client - the client connection
    * @param {String} opts.topic - the message topic
    * @param {*} opts.data - the message payload
    * @return {Promise<void>} - resolves when complete
    * @memberof @node-red/runtime_comms
    * @private
    */
    receive: async function(opts) {
        if (opts.topic) {
            receive(opts.topic,opts.data,opts.client,opts.user);
        }
    }
};
